fn chebweight(x: Vec<f32>) -> Vec<f32> {
    let n = x.len();
    // Pre-allocate the output vector with the same capacity as the input.
    let mut weights = Vec::with_capacity(n);

    // For each position, push the appropriate weight:
    // - 0.5 at the first and last indices,
    // - 1.0 everywhere else.
    for i in 0..n {
        let w = if i == 0 || i == n - 1 {
            0.5_f32
        } else {
            1.0_f32
        };
        weights.push(w);
    }

    weights
}

